    {
        $t = $lg === 'it'
            ? ['Il tuo compito', 'Pianifica', 'Agisce', 'Controlla', 'Rapporto', 'non ancora finito: passo successivo', 'Acquisto o invio?', 'prima chiede a te', 'browser, strumenti']
