        ], [
            Q('a1', L('L’abbonamento a ChatGPT include l’uso dell’API?', 'Does the ChatGPT subscription include API usage?'), [L('No, sono separati', 'No, they are separate'), L('Sì, senza limiti', 'Yes, unlimited'), L('Solo il sabato', 'Only on Saturdays'), L('Solo per le immagini', 'Only for images')], 0, L('L’API si paga a token.', 'The API is paid per token.')),
            Q('a2', L('Dove sta la chiave API nell’esempio?', 'Where is the API key in the example?'), [L('Nella variabile d’ambiente OPENAI_API_KEY', 'In the OPENAI_API_KEY environment variable'), L('Scritta nel codice', 'Written in the code'), L('Nel nome del file', 'In the file name'), L('Non serve', 'It is not needed')], 0, L('Mai nel codice.', 'Never in code.')),
            Q('a3', L('Quale proprietà contiene il testo della risposta?', 'Which property holds the answer text?'), ['output_text', 'answer', 'message', 'result'], 0, L('Nell’interfaccia Responses.', 'In the Responses interface.')),
        ], task('python', L('Con l’SDK di OpenAI crea il client e chiama `client.responses.create` con un modello a tua scelta (per esempio `model="gpt-6.1-sol"`) e `input="Dammi 3 idee per un nome di app"`, poi stampa `output_text`.', 'With the OpenAI SDK create the client and call `client.responses.create` with a model of your choice (for example `model="gpt-6.1-sol"`) and `input="Dammi 3 idee per un nome di app"`, then print `output_text`.'), "from openai import OpenAI\n", [re('client\s*=\s*OpenAI\s*\(\s*\)', L('Il client', 'The client')), re('client\.responses\.create\s*\(', L('La chiamata', 'The call')), re('model\s*=\s*["\']gpt-[\w.\-]+["\']', L('Il modello', 'The model')), re('input\s*=\s*["\']Dammi 3 idee per un nome di app["\']', L('L’input', 'The input')), re('print\s*\(\s*\w+\.output_text\s*\)', L('Stampi il testo', 'You print the text'))], '', "client = OpenAI()\nr = client.responses.create(model=\"gpt-6.1-sol\", input=\"Dammi 3 idee per un nome di app\")\nprint(r.output_text)"), [
