            dBug(pBug(), ['from openai import OpenAI', 'client = OpenAI(api_key="sk-proj-…la-mia-chiave…")', 'r = client.responses.create(model="gpt-6.1-sol", input="Ciao")'], 1, 'client = OpenAI()   # la chiave arriva da OPENAI_API_KEY', L('La chiave non va scritta nel codice.', 'The key must not be written in code.')),
