        lesson('agent', L('Ricerca approfondita, agente e app collegate', 'Deep research, agent and connected apps'), [
            P('La **ricerca approfondita** fa da sola molte ricerche sul web, legge le fonti e dopo qualche minuto consegna un **rapporto** strutturato con le citazioni: utile per confronti, rassegne e analisi di mercato. Le fonti vanno comunque aperte e controllate.', '**Deep research** runs many web searches on its own, reads the sources and after a few minutes delivers a structured **report** with citations: useful for comparisons, reviews and market analysis. The sources must still be opened and checked.'),
            P('In **modalità agente** ChatGPT svolge compiti in più passaggi usando un browser e altri strumenti: compilare una tabella da più siti, preparare una bozza di presentazione, cercare e confrontare offerte. Chiede conferma prima delle azioni importanti (un acquisto, l’invio di un messaggio) e puoi fermarlo in ogni momento.', 'In **agent mode** ChatGPT carries out multi-step tasks using a browser and other tools: filling a table from several sites, drafting a presentation, finding and comparing offers. It asks for confirmation before important actions (a purchase, sending a message) and you can stop it at any time.'),
            Fig(L(fig_chatgpt_agent('it'), fig_chatgpt_agent('en')),
                L('Una fila di riquadri: il tuo compito, pianifica, agisce, controlla, rapporto. Una freccia tratteggiata torna da «controlla» a «pianifica» finché il lavoro non è finito; sopra «agisce» un riquadro rosa avverte che per acquisti e invii l’agente chiede prima a te.', 'A row of boxes: your task, plan, act, check, report. A dashed arrow runs back from check to plan until the work is done; above act, a pink box warns that for purchases and sending the agent asks you first.'),
                L('L’agente ripete pianifica, agisce e controlla; le azioni importanti passano da te.', 'The agent repeats plan, act and check; important actions go through you.')),
            P('Le **app collegate** (connettori) danno accesso a servizi come Google Drive, Gmail, calendari o strumenti aziendali, così ChatGPT può cercare nei tuoi documenti. Collega solo ciò che serve: più accessi significa più dati esposti, e un agente che legge pagine o email può incontrare **istruzioni nascoste** pensate per ingannarlo.', '**Connected apps** (connectors) give access to services such as Google Drive, Gmail, calendars or company tools, so ChatGPT can search your documents. Connect only what you need: more access means more exposed data, and an agent reading pages or emails may meet **hidden instructions** designed to trick it.'),
            Tip('Nomi, piani e limiti di queste funzioni cambiano spesso: controlla nell’app che cosa è disponibile per il tuo account.', 'Names, plans and limits of these features change often: check in the app what is available for your account.'),
        ], [
            Q('ag1', L('Che cosa consegna la ricerca approfondita?', 'What does deep research deliver?'), [L('Una risposta di una riga senza fonti', 'A one-line answer without sources'), L('Un elenco di link da leggere da solo', 'A list of links to read yourself'), L('Un rapporto strutturato con le citazioni', 'A structured report with citations'), L('Un riassunto delle tue chat precedenti', 'A summary of your previous chats')], 2, L('Dopo qualche minuto di ricerche.', 'After a few minutes of searching.')),
            Q('ag2', L('Che cosa fa la modalità agente prima di un acquisto?', 'What does agent mode do before a purchase?'), [L('Chiede la tua conferma', 'It asks for your confirmation'), L('Paga subito con la carta salvata', 'It pays at once with the saved card'), L('Annulla sempre l’ordine', 'It always cancels the order'), L('Chiede il permesso a OpenAI', 'It asks OpenAI for permission')], 0, L('E puoi fermarlo quando vuoi.', 'And you can stop it whenever you like.')),
            Q('ag3', L('Perché collegare solo le app che servono?', 'Why connect only the apps you need?'), [L('Perché ogni app collegata rallenta il modello', 'Because every connected app slows the model'), L('Perché le app collegate costano a token', 'Because connected apps cost per token'), L('Perché si può collegare una sola app', 'Because only one app can be connected'), L('Perché più accessi espongono più dati', 'Because more access exposes more data')], 3, L('Minimo privilegio, anche con l’AI.', 'Least privilege, with AI too.')),
        ], task('text', L('Scrivi una richiesta per la ricerca approfondita che confronti tre alternative a tua scelta, indicando i **criteri** del confronto e chiedendo una **tabella** finale con le **fonti**.', 'Write a deep research request comparing three alternatives of your choice, stating the comparison **criteria** and asking for a final **table** with **sources**.'), '', [re('confront|compar', L('Chiedi un confronto', 'You ask for a comparison')), re('criteri|criteria|prezz|price|cost', L('Indichi i criteri', 'You state the criteria')), re('tabella|table', L('Chiedi una tabella', 'You ask for a table')), re('font[ie]|sources?|citazion|citation', L('Chiedi le fonti', 'You ask for sources'))], '', 'Confronta tre gestionali per piccoli studi professionali in Italia secondo questi criteri: prezzo annuo, fatturazione elettronica, assistenza in italiano. Chiudi con una tabella e le fonti per ogni dato.'), [
            dMatch(pMatch(), [[L('Ricerca approfondita', 'Deep research'), L('Rapporto con citazioni', 'Report with citations')], [L('Modalità agente', 'Agent mode'), L('Compiti in più passaggi', 'Multi-step tasks')], [L('App collegate', 'Connected apps'), L('Accesso ai tuoi servizi', 'Access to your services')], [L('Conferma', 'Confirmation'), L('Prima delle azioni importanti', 'Before important actions')]], L('ChatGPT che lavora per te.', 'ChatGPT working for you.')),
            dFlash(pFlash(), [[L('Le fonti di un rapporto vanno comunque controllate', 'A report’s sources must still be checked'), true], [L('La modalità agente non si può fermare', 'Agent mode cannot be stopped'), false], [L('Una pagina web può contenere istruzioni nascoste per un agente', 'A web page can contain hidden instructions for an agent'), true], [L('Collegare tutte le app è sempre più sicuro', 'Connecting every app is always safer'), false]], L('Delegare, ma sorvegliare.', 'Delegate, but supervise.')),
        ]),
